import React, { useEffect, useState } from 'react';
import { useNavigation } from '@react-navigation/native';
import type { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { SafeAreaView, Image, ImageBackground, FlatList, TouchableOpacity, View, Dimensions, Alert } from 'react-native';
import { Text, Spacer, SimpleHeader, LoadingView, LoadingBlockerView, useTheme } from '@core/ui';
import { formatMoney } from '@src/utils/currency';
import useCSS from '@src/presentation/style';
import { COUNTER, CURRENCY, HAS_DEPOSIT, HAS_RESTRAINT } from '@src/utils/constants';
import { useDispatch, useSelector } from '@src/lib/redux';
import { getListDepositAccounts } from './thunk';
import { IAccount } from '@src/domain/entities/loan_collateral/depositAccount';
import NoDataView from './components/NoDataView';
import { formatDate, useTranslation } from '@core/service';

import { selectAccounts, selectError, selectStatus, selectSystemDate } from './selector';
import moment from 'moment';
import confirmSlice from '@src/presentation/loan_collateral/collateral_confirm/slice';
import { selectClientNo } from '@src/presentation/loan_products/selector';
import getImg from '@src/utils/getImg';
import slice from './slice';
import HighlightTitle from '@src/presentation/components/text/HighlightTitle';
import BottomSheetLoanInfo from './components/BottomSheetLoanInfo';
import CustomHeader from '@src/presentation/components/header/CustomHeader';
import FastImage from 'react-native-fast-image';

// 10 triệu
const LOAN_MIN = 10000000;
// 1 tỷ
const LOAN_MAX = 1000000000;

const CollateralAccountsScreen = () => {
    const navigation = useNavigation<MainStackNavigationProp>();
    const dispatch = useDispatch();
    const { theme } = useTheme();
    const css = useCSS();
    const { t } = useTranslation(['module_collateral']);

    const clientNo = useSelector(selectClientNo);
    const status = useSelector(selectStatus);
    const error = useSelector(selectError);
    const accounts = useSelector(selectAccounts);
    const systemDate = useSelector(selectSystemDate);

    const handleSelectAccount = (account: IAccount) => {
        dispatch(confirmSlice.actions.setAccount(account));
        navigation.navigate('collateral_amount');
    };

    const checkInvalidAccount = (item: IAccount) => {
        return Number(item.balance) < LOAN_MIN || moment(item.maturityDate).isSame(systemDate);
    };

    useEffect(() => {
        dispatch(getListDepositAccounts({ clientNo }));
    }, []);

    useEffect(() => {
        if (error) {
            Alert.alert('Thông báo', error);
        }
    }, [error]);

    const windowWidth = Dimensions.get('window').width;
    const [show, setShow] = useState(false);

    return (
        <>
            <ImageBackground source={getImg('/assets/images/bg_body.jpg')} resizeMode='cover' style={[css.flex_1]}>
                <SafeAreaView style={[css.flex_1]}>
                    {/* <SimpleHeader allowGoBack={true} title={t('screen_accounts.header_title')} onBackPress={() => navigation.goBack()} /> */}
                    <CustomHeader title={t('screen_accounts.header_title')} />
                    {status === 'loading' ? (
                        <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />
                    ) : accounts && accounts?.length > 0 ? (
                        <>
                            <HighlightTitle
                                containerStyle={[css.mh_xLarge]}
                                title={t('screen_accounts.title')}
                                titleStyle={[css.mt_medium, css.text_title_200, css.font_semibold]}
                                subtitle={t('screen_accounts.sub_title')}
                                subtitleStyle={[css.text_subheadline, css.font_regular]}
                            />
                            <FlatList
                                style={[css.ph_medium, css.mv_medium]}
                                data={accounts}
                                keyExtractor={(item, index) => `${item?.accountNo}-${index}`}
                                renderItem={({ item, index }) => {
                                    if ((item.hasRestraint !== HAS_RESTRAINT && item.hasDeposit !== HAS_DEPOSIT) || item.openMethod === COUNTER) {
                                        return (
                                            <TouchableOpacity
                                                key={item?.accountNo}
                                                onPress={() => handleSelectAccount(item)}
                                                disabled={checkInvalidAccount(item)}>
                                                {index > 0 ? <Spacer height={16} /> : null}
                                                <View
                                                    style={[
                                                        css.bg_white,
                                                        css.rounded_medium,
                                                        css.shadow_100,
                                                        checkInvalidAccount(item) ? css.opacity_50 : css.opacity_100,
                                                    ]}>
                                                    <View style={[css.row, css.justify_start, css.pv_base, css.ph_medium]}>
                                                        <FastImage
                                                            source={getImg('/assets/images/icon_account.png')}
                                                            style={[css.ratio_square, css.mr_regular, { width: theme.Scaling.ms(48) }]}
                                                        />
                                                        <View style={css.flex_1}>
                                                            <View style={[css.row, css.justify_between]}>
                                                                <Text style={[css.text_neutral_600, css.text_caption_100, css.font_regular]}>
                                                                    {t(`screen_accounts.balance`)}
                                                                </Text>
                                                                <Text style={[css.text_caption_100, css.text_neutral_600, css.font_regular]}>
                                                                    {t(`screen_accounts.accountNo`)}: {item.accountNo}
                                                                </Text>
                                                            </View>
                                                            <Spacer height={4} />
                                                            <View style={[css.row, css.justify_between, css.items_start]}>
                                                                <Text style={[css.text_body, css.font_semibold]}>
                                                                    {formatMoney(item.balance)} {CURRENCY}
                                                                </Text>
                                                                <Text
                                                                    style={[
                                                                        css.text_caption_200,
                                                                        css.font_semibold,
                                                                        css.bg_orange_600,
                                                                        css.rounded_full,
                                                                        css.ph_small,
                                                                    ]}>
                                                                    {item.intRate}%/{t(`screen_accounts.year`)}
                                                                </Text>
                                                            </View>
                                                        </View>
                                                    </View>
                                                    <View style={[css.border_t_1, css.border_t_neutral_300]} />
                                                    <View style={[css.row, css.p_medium]}>
                                                        <View style={[css.flex_1]}>
                                                            <View style={[css.row]}>
                                                                <Text style={[css.text_caption_100, css.text_neutral_600, css.font_regular]}>
                                                                    {t(`screen_accounts.maturityDate`)}
                                                                </Text>
                                                                <Spacer width={4} />
                                                                <Text style={[css.text_caption_100, css.text_neutral_600, css.font_bold]}>
                                                                    {formatDate(item?.maturityDate)}
                                                                </Text>
                                                            </View>
                                                            <View style={[css.row]}>
                                                                <Text style={[css.text_caption_100, css.text_neutral_600, css.font_regular]}>
                                                                    {t(`screen_accounts.openMethod`)}
                                                                </Text>
                                                                <Spacer width={4} />
                                                                <Text style={[css.text_caption_100, css.text_neutral_600, css.font_bold]}>
                                                                    {item?.openMethod === 'COUNTER' ? t(`screen_accounts.COUNTER`) : t(`screen_accounts.AUTO`)}
                                                                </Text>
                                                            </View>
                                                        </View>
                                                        <View>
                                                            <Text style={[css.text_neutral_600, css.text_right, css.text_caption_100, css.font_regular]}>
                                                                {t(`screen_accounts.depositAcctAccruedAmt`)}
                                                            </Text>
                                                            <View style={[css.row, css.justify_end, css.items_center]}>
                                                                <Text style={[css.text_subheadline, css.font_bold, css.text_red_600]}>
                                                                    {formatMoney(item?.depositAcctAccruedAmt)}
                                                                </Text>
                                                                <TouchableOpacity onPress={() => setShow(true)}>
                                                                    <FastImage
                                                                        source={getImg('/assets/images/icons/icon_info_gray_600.png')}
                                                                        resizeMode='contain'
                                                                        style={[
                                                                            { width: theme.Size.Horizontal.Medium, height: theme.Size.Vertical.Medium },
                                                                            css.ml_small,
                                                                        ]}
                                                                    />
                                                                </TouchableOpacity>
                                                            </View>
                                                        </View>
                                                    </View>
                                                </View>
                                            </TouchableOpacity>
                                        );
                                    } else {
                                        return null;
                                    }
                                }}
                            />
                        </>
                    ) : (
                        <NoDataView />
                    )}
                </SafeAreaView>
            </ImageBackground>
            <BottomSheetLoanInfo show={show} onClose={() => setShow(false)} />
        </>
    );
};

export default CollateralAccountsScreen;
