import { injectable } from 'inversify';
import { CmsService } from '@core/service';
import { ICmsLoanRegisterTnCRepository } from '@src/domain/interfaces/cms/loan_register/loanRegisterTnC';
import { CmsLoanRegisterTnC } from '@src/domain/entities/cms/loan_register/loanRegisterTnC';
import { DOMAIN_CMS } from '@src/config';

const getCmsLoanRegisterTnCUrl = '/dl-loan-register-term-and-conditions';
const defaultSegment = 'default';

@injectable()
export class CmsLoanRegisterTnCRepository extends CmsService implements ICmsLoanRegisterTnCRepository {
    constructor() {
        super({ baseURL: DOMAIN_CMS });
    }
    async getCmsLoanRegisterTnC(segment: string): Promise<CmsLoanRegisterTnC | null> {
        try {
            const response = await this.get<CmsLoanRegisterTnC>(getCmsLoanRegisterTnCUrl, {
                params: {
                    'populate': '*',
                },
            });
            return response.data as CmsLoanRegisterTnC ?? null;
        } catch (error) {
            throw error;
        }
    }
}
