import React, { useCallback, useEffect, useState } from 'react';
import { Alert, KeyboardAvoidingView, SafeAreaView, Text, View } from 'react-native';
import type { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useFocusEffect, useNavigation } from '@react-navigation/native';
import { useSelector } from 'react-redux';
import { selectStatus } from './RegisterCVPSelector';
import useCSS from '@src/presentation/style/index';
import { useDispatch } from '@src/lib/redux';
// import { fetchLocationDetail } from '@src/presentation/weather/WeatherSearch';
import { IS_IOS, Storage, STORAGE_KEY, useTranslation } from '@core/service';
import { ScrollView } from 'react-native-gesture-handler';
import { WebView } from 'react-native-webview';
import { createStyles, GradientButton, LoadingBlockerView, SimpleHeader, useTheme } from '@core/ui';
import DataSelectList from '@src/presentation/components/selectList/type';
import { LoanRegisterSlice } from '../register_confirm/redux/slice';
import BottomSheetSelectList from '@src/presentation/components/bottomSheetSelectList';
import { fetchLocationDetail } from '@src/presentation/weather/WeatherSearch';
import { SCREEN_HEIGHT } from '@gorhom/bottom-sheet';
import CustomHeader from '@src/presentation/components/header/CustomHeader';

const RegisterCVPScreen: React.FC = () => {
    const css = useCSS();
    const navigation = useNavigation<MainStackNavigationProp>();
    const status = useSelector(selectStatus);
    const dispatch = useDispatch();
    const styles = useStyles();
    const { t } = useTranslation(['module_register']);
    const { theme } = useTheme()
    const [showListOptionRegisterLoan, setShowListOptionRegisterLoan] = useState<boolean>(false);
    const [showWebView, setShowWebView] = useState<boolean>(false);

    const listOptionRegisterLoan = [
        {
            id: 1,
            title: `${t('screen_cvp.register_loan_for_personal')}`,
            fn: () => {
                dispatch(LoanRegisterSlice.actions.updateFlowRegister('personal'));
                navigation.navigate('register_confirm');
            },
        },
        {
            id: 2,
            title: `${t('screen_cvp.register_loan_for_other')}`,
            fn: () => {
                dispatch(LoanRegisterSlice.actions.resetLoanRegister())
                dispatch(LoanRegisterSlice.actions.updateFlowRegister('other'));
                navigation.navigate('register_confirm');
            },
        },
    ] as DataSelectList[];
    const handlePressSubmit = () => {
        setShowListOptionRegisterLoan(true);
    };
    useEffect(() => {
        dispatch(fetchLocationDetail('test')).then((res) => {
            if (!(res.payload as any)?.data?.accessToken) {
                Alert.alert('Thông báo', 'Lỗi không xác định');
            } else {
                // dispatch(cardSlice.actions.setToken((res.payload as any)?.data?.token))
                Storage.save(STORAGE_KEY.USER_AUTH, (res.payload as any)?.data)
            }
        })
    }, []);
    useFocusEffect(
        useCallback(() => {
            console.log('re-reder register cvp');
            setShowWebView(true);
            return () => {
                setShowWebView(false);
                console.log('return re-reder register cvp');
            }
        }, [])
    )
    return (
        <>
            <View style={[css.relative, css.flex_1]}>
                {showWebView &&
                    <WebView
                        source={{ uri: 'https://chic-starburst-059945.netlify.app/cvp_loan_register/index.html' }}
                        allowsInlineMediaPlayback={true}
                        mediaPlaybackRequiresUserAction={false}
                        style={[{ minHeight: SCREEN_HEIGHT }]}
                        injectedJavaScript={`
                        document.addEventListener("DOMContentLoaded", function() {
                            var video = document.querySelector("video");
                            if (video) {
                            video.play().catch(error => console.log("Autoplay blocked:", error));
                            }
                        });
                        `
                        }
                        onLoad={() => { console.log('onload webview'); }}
                        onLoadEnd={() => { console.log('onload end webview'); }}
                    />
                }
                <View style={[css.absolute, css.shrink_0, { top: 0, left: 0, bottom: 0, right: 0 }]}>
                    <SafeAreaView style={[css.flex_1]}>
                        {/* <SimpleHeader
                            allowGoBack
                            onBackPress={() => {
                                navigation.goBack();
                            }}
                        /> */}
                        <CustomHeader themeColor={theme.Colors.Base.White} />
                    </SafeAreaView>
                    <View style={[css.mt_auto, css.p_medium, { backgroundColor: 'rgba(255,255,255,.5)' }]}>
                        <SafeAreaView>
                            <GradientButton gradientProps={{ type: 'primary' }} title={t('screen_cvp.label_submit')} onPress={handlePressSubmit} />
                        </SafeAreaView>
                    </View>
                </View>
                {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
            </View>
            {status === 'loading' ? <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> : null}
            <BottomSheetSelectList
                title={t('screen_cvp.title_list_options_register_loan')}
                show={showListOptionRegisterLoan}
                listSelect={listOptionRegisterLoan}
                onClose={() => setShowListOptionRegisterLoan(false)}
            />
        </>
    );
};

export default RegisterCVPScreen;
const useStyles = createStyles(Theme => ({
    webview: {
        flexShrink: 0,
        height: '100%'
    },
    webViewBottom: {
        position: 'absolute',
        bottom: 20,
        left: 0,
        right: 0,
        height: 50,
        backgroundColor: 'white',
        justifyContent: 'center',
        alignItems: 'center',
    },
    webViewHeader: {
        position: 'absolute',
        top: 10,
        left: 0,
        right: 0,
        height: 50,
        backgroundColor: 'transparent',
        justifyContent: 'center',
        alignItems: 'center',
    },
}));