import { View, Image, TouchableOpacity } from 'react-native';
import React, { ReactNode, useEffect } from 'react';
import { createStyles, Text, Theme, useTheme } from '@core/ui';
import useCSS from '@src/presentation/style';
import { useTranslation } from '@core/service'
import getImg from '@src/utils/getImg';
import FastImage from 'react-native-fast-image';

export type sectionFieldProps = {
    id?: string;
    title: string;
    render?: ReactNode;
    fn?: () => void;
    style?: Record<string, string | number>;
    divider?: boolean;
    isRequired?: boolean;
    value?: string;
    showArrow?: boolean;
    allowEdit?: boolean;
    icon?: string;
    iconStyle?: Record<string, string | number>;
    titleAction?: string;
};
const SectionField = (props: sectionFieldProps) => {
    const { theme } = useTheme()
    const styles = useStyles();
    const css = useCSS();
    const { t } = useTranslation('module_register');

    return (
        <View style={[css.bg_white, props.style || []]}>
            <View style={[css.ph_medium]}>
                {props.divider && <View style={{ borderTopWidth: 1, borderColor: theme.Colors.Border.Neutral300 }} />}
                <View style={[css.row, css.justify_between, css.pv_medium, css.items_center]}>
                    <View style={[css.shrink_0, { width: '50%', marginRight: theme.Size.Horizontal.Base }]}>
                        <Text style={{ ...theme.Typography.TextSubheadline.Regular, color: theme.Colors.Text.Neutral600 }}>{props.title}</Text>
                        {props?.isRequired && <Text style={{ ...theme.Typography.TextCaption100.Regular, color: theme.Colors.Main.Red }}>{t('screen_confirm.is_required')}</Text>}
                    </View>
                    <TouchableOpacity style={[css.flex_1, css.pl_base]} hitSlop={{ top: 20, bottom: 20, left: 20, right: 20 }} disabled={!props?.allowEdit} onPress={props.fn}>
                        <View style={[css.row, css.items_center, css.justify_end]}>
                            {props?.value ?
                                <Text style={styles.value}>{props?.value}</Text>
                                :
                                (props?.allowEdit ? <Text style={{ ...theme.Typography.TextSubheadline.SemiBold, color: theme.Colors.Text.Neutral500 }}>{props.titleAction || t('screen_confirm.action_input_title')}</Text> : '')
                            }
                            {((props?.showArrow || !props?.value) && props?.allowEdit) &&
                                <FastImage style={[{ height: theme.Size.Vertical.Regular, width: theme.Size.Horizontal.Base }, css.ml_base, props.iconStyle]} resizeMode='contain' source={getImg(props.icon || '/assets/images/icons/right_arrow.png')} />
                            }
                        </View>
                    </TouchableOpacity>
                </View>
            </View>
        </View>
    );
}

const useStyles = createStyles((theme: Theme) => {
    return {
        value: {
            ...theme.Typography.TextSubheadline.SemiBold,
            maxWidth: theme.Size.Horizontal.Titanic,
            flexShrink: 0,
            textAlign: 'right'
        },
        title: {
            ...theme.Typography.Title200.Semibold,
        },
        titleWrapper: {
            marginTop: theme.Size.Vertical.Medium,
            justifyContent: 'center',
        },
        highLightAction: {
            ...theme.Typography.TextSubheadline.SemiBold,
            color: theme.Colors.Text.Error,
        },
        sectionWrapper: {
            borderWidth: 1,
            borderColor: theme.Colors.Border.Neutral300,
            overflow: 'hidden',
            borderRadius: theme.BorderRadius.md,
            backgroundColor: theme.Colors.Background.White,
            marginTop: theme.Size.Vertical.Medium,
            // marginHorizontal: theme.Size.Horizontal.Medium
        },
    };
});

const MemoizedSectionField = React.memo(SectionField);

export { MemoizedSectionField as SectionField };
