// import { District } from '@src/domain/entities/card_management/district';

enum UnitType {
    Province,
    District,
    Ward
}
interface CardSelectAddressBottomProps {
    // bottomSheetId: string;
    // clientNo: string;
    // callbackAddress: (address: string) => void;
    listProvince: Province[];
    onSelectAddr: (item: Record<string, Province | District | Ward>) => void;
    onClose?: () => void;
}
const FilterAddress = (props: CardSelectAddressBottomProps) => {
    // const { bottomSheetId } = props;
    const { t } = useTranslation(['module_register']);
    const {
        onSelectAddr, onClose
    } = props;
    const [listProvince, setListProvince] = useState<Province[]>([]);
    const [listDistrict, setListDistrict] = useState<District[]>([]);
    const [listWard, setListWard] = useState<Ward[]>([]);
    const { theme } = useTheme();
    const styles = useStyles();
    const [search, setSearch] = useState<string>("");
    const [province, setProvince] = useState<Province>();
    const [district, setDistrict] = useState<District>();
    const [ward, setWard] = useState<Ward>();
    const [unit, setUnit] = useState<UnitType>(UnitType.Province);
    const [listSearchProvince, setListSearchProvince] = useState<Province[]>([]);
    const [listSearchDistrict, setListSearchDistrict] = useState<District[]>([]);
    const [listSearchWard, setListSearchWard] = useState<Ward[]>([]);
    const dispatch = useDispatch();
    const [showBottomSheetInput, setShowBottomSheetInput] = useState(false);
    const searchRef = useRef<SearchBarFunc>(null);
    const [loading, setLoading] = useState(false);

    const setTextSearch = (text: string) => {
        setSearch(text)
    };
    const selectProvince = (item: Province) => {
        setProvince(item);
        setDistrict({} as District);
        setWard({} as Ward);
        // onSelectProvince(item);
        if (!item.id) return;
        setLoading(true);
        dispatch(getDistrictListThunk({ provinceId: item.id })).then((res) => {
            const resp = (res?.payload as DistrictResponse)
            if (resp?.resultCode === '00') {
                setListDistrict((res?.payload as DistrictResponse)?.data || []);
                setTimeout(() => {
                    setLoading(false);
                    setUnit(UnitType.District);
                }, 200);
            }
        });
    };
    const selectDistrict = (item: District) => {
        setDistrict(item);
        setWard({} as Ward);
        // onSelectDistrict(item);
        if (!item.id) return;
        setLoading(true);
        dispatch(getWardListThunk({ provinceId: item.provinceId, districtId: item.id })).then((res) => {
            const resp = (res?.payload as WardResponse)
            if (resp?.resultCode === '00') {
                console.log('\x1b[31m getWardListThunk', JSON.stringify(res?.payload));
                setListWard((res?.payload as WardResponse)?.data || []);
                setTimeout(() => {
                    setLoading(false);
                    setUnit(UnitType.Ward);
                }, 200);
            }

        });;
    };
    const selectWard = (item: Ward) => {
        setWard(item);
        // onSelectWard(item);
        onSelectAddr({
            province: province || ({} as Province),
            district: district || ({} as District),
            ward: item
        })
        setShowBottomSheetInput(true);
    }
    const handleCloseBSAddress = () => {
        onClose?.()
    }
    const handleResetAddress = () => {
        selectProvince({} as Province);
        selectDistrict({} as District);
        // selectWard({} as Ward);
        setUnit(UnitType.Province);
    }
    const handleSearch = (searchText: string) => {
        switch (unit) {
            case UnitType.Province:
                setListSearchProvince(listProvince.filter(item => item.name.toLowerCase().includes(searchText.toLowerCase())));
                break;
            case UnitType.District:
                setListSearchDistrict(listDistrict.filter(item => item.name.toLowerCase().includes(searchText.toLowerCase())));
                break;
            case UnitType.Ward:
                setListSearchWard(listWard.filter(item => item.name.toLowerCase().includes(searchText.toLowerCase())));
                break;
        }
    }
    const renderListUnit = () => {
        switch (unit) {
            case UnitType.Province:
                return (
                    <View style={{
                        height: 300
                    }}>
                        <FlatList data={listSearchProvince} keyboardShouldPersistTaps='handled'
                            renderItem={({ item, index }) => (
                                <TouchableOpacity onPress={() => selectProvince(item)} key={index}>
                                    <View style={[styles.container]}>
                                        <View style={[styles.containerContent]}>
                                            <Text style={{ flex: 1 }}>
                                                {item.name}
                                            </Text>
                                            <FastImage style={[{ height: theme.Size.Vertical.Regular, width: theme.Size.Horizontal.Base }]} resizeMode="contain" source={getImg('/assets/images/icons/right_arrow.png')} />
                                        </View>
                                        <View style={{ height: 1, backgroundColor: theme.Colors.Background.Neutral300, width: '100%' }} />
                                    </View>
                                </TouchableOpacity>
                            )}
                            keyExtractor={(item, index) => `key-province-${item.id}-${index}`}
                        />
                    </View>
                );
            case UnitType.District:
                return (
                    <View style={{
                        height: 300
                    }}>
                        <FlatList
                            data={listSearchDistrict}
                            keyboardShouldPersistTaps='handled'
                            renderItem={({ item, index }) => (
                                <TouchableOpacity onPress={() => selectDistrict(item)} key={index}>
                                    <View style={[styles.container]}>
                                        <View style={[styles.containerContent]}>
                                            <Text style={{ flex: 1 }}>
                                                {item.name}
                                            </Text>
                                            <FastImage style={[{ height: theme.Size.Vertical.Regular, width: theme.Size.Horizontal.Base }]} resizeMode='contain' source={getImg('/assets/images/icons/right_arrow.png')} />
                                        </View>
                                        <View style={{ height: 1, backgroundColor: theme.Colors.Background.Neutral300, width: '100%' }} />
                                    </View>
                                </TouchableOpacity>
                            )}
                            keyExtractor={(item, index) => `key-district-${item.id}-${index}`}
                        />
                    </View>
                );
            case UnitType.Ward:
                return (
                    <View style={{
                        height: 300
                    }}>
                        <FlatList
                            data={listSearchWard}
                            keyboardShouldPersistTaps='handled'
                            renderItem={({ item, index }) => (
                                <TouchableOpacity onPress={() => {
                                    selectWard(item)
                                }} key={index}>
                                    <View style={[styles.container]}>
                                        <View style={[styles.containerContent]}>
                                            <Text style={{ flex: 1 }}>
                                                {item.name}
                                            </Text>
                                            {/* {props.iconRight} */}
                                        </View>
                                        <View style={{ height: 1, backgroundColor: theme.Colors.Background.Neutral300, width: '100%' }} />
                                    </View>
                                </TouchableOpacity>
                            )}
                            keyExtractor={(item, index) => `key-ward-${item.id}-${index}`}
                        />
                    </View>
                );
        }
    }
    useFocusEffect(
        useCallback(() => {
            setLoading(true);
            dispatch(getProvinceListThunk()).then((res) => {
                console.log('\x1b[31m getProvinceListThunk', JSON.stringify(res?.payload));
                setListProvince((res?.payload as ProvinceResponse)?.data || []);
                setListSearchProvince((res?.payload as ProvinceResponse)?.data || []);
                setTimeout(() => {
                    setLoading(false);
                }, 200);
            });
            // dispatch(
            //     getProvinceListByClientNumberThunk({ clientNo: props.clientNo }));
        }, []),
    );
    useEffect(() => {
        setSearch('');
        if (searchRef) {
            searchRef.current?.reset()
        }
    }, [unit]);
    useEffect(() => {
        setListSearchDistrict(listDistrict);
        setListSearchWard(listWard);
    }, [listDistrict, listWard]);
    useEffect(() => {
        if (listProvince.length === 0) {
            dispatch(getProvinceListThunk());
        }
    }, []);
    useEffect(() => {
        if (search === '') {
            setListSearchProvince(listProvince);
            setListSearchDistrict(listDistrict);
            setListSearchWard(listWard);
            return;
        }
        let debounceSearch = setTimeout(() => {
            handleSearch(search)
        }, 300);
        return () => {
            clearTimeout(debounceSearch);
        }
    }, [search]);
    return (
        <View style={styles.containerAddress}>
            {loading && <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} />}
            <SearchBar
                ref={searchRef}
                style={styles.searchStyle}
                onSearch={setTextSearch} />
            {
                (ward || district || province)
                    ? (
                        <View style={styles.addressStyle}>
                            {/* <IMaskGroup /> */}
                            <FastImage style={{ width: theme.Size.Horizontal.xLarge, height: theme.Size.Vertical.xLarge }} resizeMode="contain" source={getImg('/assets/images/icons/icon_location.png')} />
                            <Text style={styles.txtAddress}>
                                {`${(ward?.name ? `${ward.name}, ` : '')} ${(district?.name ? `${district.name}, ` : '')} ${(province?.name ? `${province.name}` : '')}`}
                            </Text>
                            <TouchableOpacity
                                onPress={handleResetAddress}>
                                <FastImage style={{ width: theme.Size.Horizontal.xLarge, height: theme.Size.Vertical.xLarge }} resizeMode="contain" source={getImg('/assets/images/icons/icon_delete.png')} />
                            </TouchableOpacity>
                        </View>
                    )
                    : <></>
            }
            <View style={{ flexDirection: 'row' }}>
                <View>
                    <TouchableOpacity
                        style={styles.unitStyle}
                        onPress={() => setUnit(UnitType.Province)}>
                        <Text style={{
                            ...theme.Typography.TextSubheadline.Bold,
                            color: unit !== UnitType.Province ? theme.Colors.Text.Neutral500 : 'red'
                        }}>
                            {t('screen_confirm.title_province')}
                        </Text>
                    </TouchableOpacity>
                    {
                        unit === UnitType.Province ? <View style={{ height: 2, backgroundColor: 'red' }}></View> : null
                    }
                </View>
                <View>
                    <TouchableOpacity
                        style={styles.unitStyle}
                        onPress={() => setUnit(UnitType.District)}>
                        <Text style={{
                            ...theme.Typography.TextSubheadline.Bold,
                            color: unit !== UnitType.District ? theme.Colors.Text.Neutral500 : 'red'
                        }}>
                            {t('screen_confirm.title_district')}
                        </Text>
                    </TouchableOpacity>
                    {
                        unit === UnitType.District ? <View style={{ height: 2, backgroundColor: 'red' }}></View> : null
                    }
                </View>
                <View>
                    <TouchableOpacity
                        style={styles.unitStyle}
                        onPress={() => setUnit(UnitType.Ward)}>
                        <Text style={{
                            ...theme.Typography.TextSubheadline.Bold,
                            color: unit !== UnitType.Ward ? theme.Colors.Text.Neutral500 : 'red'
                        }}>
                            {t('screen_confirm.title_ward')}
                        </Text>
                    </TouchableOpacity>
                    {
                        unit === UnitType.Ward ? <View style={{ height: 2, backgroundColor: 'red' }}></View> : null
                    }
                </View>
            </View>
            <View style={styles.line}>
            </View>
            <View style={{
                marginTop: 16,
                overflow: 'hidden',
            }}>
                {renderListUnit()}
            </View>
            <Spacer height={16} />
            <SafeAreaView>
                <ActionButton type={'secondary'} activeOpacity={1} title={t('screen_confirm.lable_close_addr')} onPress={handleCloseBSAddress} />
            </SafeAreaView>
        </View>
    );
};
export default FilterAddress;

