import React, { useRef, useState } from 'react';
import { View, Image, TouchableOpacity } from 'react-native';
import { Text, BottomSheetManager, BottomSheet, BottomSheetRef } from '@core/ui';
import useCSS from '@src/presentation/style';
import { useDispatch, useSelector } from '@src/lib/redux';
import slice from '@src/presentation/loan_collateral/collateral_confirm/slice';
import { selectBranches, selectBranchSelected, selectCustomerInfo, selectEmail, selectIsCounter } from '../selector';
import ContentBranch from '@src/presentation/components/contentBranch';
import type { IBranch } from '@src/domain/entities/common/branch';
import ContentInput from '@src/presentation/components/contentInput';
import { validator } from '@src/utils/validator';
import getImg from '@src/utils/getImg';
import { useTranslation } from 'react-i18next';
import { CustomerInfo } from '@src/domain/entities/loan_collateral/get_init_loan_proposal';
import { IS_IOS } from '@core/service';
import BottomSheetBranch from '@src/presentation/components/bottomSheetBranch';
import FastImage from 'react-native-fast-image';

const SectionCustomerInfo = () => {
    const css = useCSS();
    const dispatch = useDispatch();
    const { t } = useTranslation(['module_collateral']);

    const refBSEmail = useRef<BottomSheetRef>(null);
    const email = useSelector(selectEmail);
    const handleChangeEmail = (text: string) => {
        dispatch(slice.actions.setEmail(text));
        refBSEmail?.current?.close();
    };

    const refBSBranch = useRef<BottomSheetRef>(null);
    const branches = useSelector(selectBranches);
    const branchSelected = useSelector(selectBranchSelected);
    const handleBranch = (item: IBranch | string) => {
        dispatch(slice.actions.setBranch(item));
        refBSBranch?.current?.close();
    };

    const customerInfo = useSelector(selectCustomerInfo) as CustomerInfo;
    const isCounter = useSelector(selectIsCounter);

    const [openBranch, setOpenBranch] = useState(false);

    return (
        <View style={[]}>
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.clientName')}</Text>
                <Text style={[css.flex_1, css.text_subheadline, css.font_semibold, css.text_right, css.ml_base]}>{customerInfo?.clientName || ''}</Text>
            </View>
            <View style={[css.border_t_1, css.border_t_neutral_300]} />
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.globalId')}</Text>
                <Text style={[css.flex_1, css.text_subheadline, css.font_semibold, css.text_right, css.ml_base]}>{customerInfo?.globalId}</Text>
            </View>
            <View style={[css.border_t_1, css.border_t_neutral_300]} />
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.phoneNumber')}</Text>
                <Text style={[css.flex_1, css.text_subheadline, css.font_semibold, css.text_right, css.ml_base]}>{customerInfo?.phoneNumber}</Text>
            </View>
            <View style={[css.border_t_1, css.border_t_neutral_300]} />
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.email')}</Text>
                <TouchableOpacity
                    style={[css.row, css.items_center, css.justify_end]}
                    onPress={() => {
                        BottomSheetManager.show({
                            render: (portalId) => (
                                <BottomSheet
                                    ref={refBSEmail}
                                    id={portalId}
                                    title={t('screen_confirm.bs_title_email')}
                                    safeAreaBottomOffset={IS_IOS ? 370 : 0}
                                    snapPoints={['60%']}>
                                    <ContentInput
                                        label={t('screen_confirm.label_email')}
                                        value={email}
                                        onSubmit={handleChangeEmail}
                                        validate={validator.validateEmail}
                                    />
                                </BottomSheet>
                            ),
                        });
                    }}>
                    <Text style={[css.text_subheadline, css.font_semibold, css.text_right, css.ml_base]}>{email}</Text>
                    <FastImage
                        source={getImg('/assets/images/icons/right_arrow.png')}
                        resizeMode='contain'
                        style={[css.w_regular, css.ratio_square, css.ml_base]}
                    />
                </TouchableOpacity>
            </View>
            <View style={[css.border_t_1, css.border_t_neutral_300]} />
            <View style={[css.row, css.items_center, css.pv_regular]}>
                <Text style={[css.flex_1, css.text_subheadline, css.text_neutral_600, css.font_regular]}>{t('screen_confirm.branchName')}</Text>
                <TouchableOpacity
                    disabled={isCounter} //nếu mở tại quầy thì ko cho chọn branch
                    style={[css.flex_1, css.ml_base]}
                    onPress={() => {
                        setOpenBranch(true);
                    }}>
                    <View style={[css.row, css.items_center, css.justify_end]}>
                        <Text style={[, css.text_subheadline, css.font_semibold, css.text_right]}>{branchSelected.branchName}</Text>
                        {!isCounter ? (
                            <FastImage
                                source={getImg('/assets/images/icons/right_arrow.png')}
                                resizeMode='contain'
                                style={[css.w_regular, css.ratio_square, css.ml_base]}
                            />
                        ) : null}
                    </View>
                </TouchableOpacity>
            </View>
            <BottomSheetBranch
                show={openBranch}
                title={t('screen_confirm.bs_title_branch')}
                data={branches}
                selected={branchSelected?.branchId}
                onSubmit={handleBranch}
                onClose={() => setOpenBranch(false)}
            />
            ;
        </View>
    );
};

export default SectionCustomerInfo;
