import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { ISubmitLoanProposalRepository } from '@src/domain/interfaces/loan_collateral/submit_loan_proposal';
import { SubmitLoanProposalPayload } from './submit_loan_proposal_query';

export class SubmitLoanProposalHandler {
    private readonly _submitLoanProposalRepository: ISubmitLoanProposalRepository;

    constructor(@inject(TYPES.ISubmitLoanProposalRepository) submitLoanProposalRepository: ISubmitLoanProposalRepository) {
        this._submitLoanProposalRepository = submitLoanProposalRepository;
    }

    handle(dataReq: SubmitLoanProposalPayload) {
        return this._submitLoanProposalRepository.submitLoanProposal(dataReq);
    }
}
