import { injectable } from 'inversify';
import { CmsService } from '@core/service';
import { ITnCLendingRepository } from '@src/domain/interfaces/cms/loan_collateral/tnCLending';
import { TnCLendingDataRes } from '@src/domain/entities/cms/loan_collateral/tnCLending';

@injectable()
export class TnCLendingRepository
    extends CmsService
    implements ITnCLendingRepository {
    constructor() {
        super();
    }

    async tnCLending(segment: string): Promise<TnCLendingDataRes> {        
        try {
                const response = await this.get<TnCLendingDataRes>('/dl-td-lending-term-and-conditions', {
                    params: {
                        'populate': segment,
                    },
                });
                return response.data as TnCLendingDataRes ?? null;
            } catch (error) {
                throw error;
            }
    }
}
