import { View, Text, FlatList, TouchableOpacity } from 'react-native'
import React, { useEffect, useRef, useState } from 'react'
import { createStyles, RadioButton, useTheme, Theme } from '@core/ui';
import { registerStaticData } from '@src/domain/entities/cms/loan_register/registerStaticData';

type SelectOptionProps = {
    listOption: registerStaticData[] | undefined;
    onSelected?: (data: registerStaticData) => void;
}

export default function SelectOption(Props: SelectOptionProps) {
    const { theme } = useTheme()
    const styles = useStyles();
    const [optionSelected, setOptionSelected] = useState<string>('');
    const renderOption = ({ item, index }: { item: registerStaticData, index: number }) => {
        return (
            <TouchableOpacity
                onPress={() => handleRadioPress(item)}
                style={[styles.row, index > 0 && { borderTopWidth: theme.Size.Vertical.XXSmall, borderTopColor: theme.Colors.Border.Neutral300 }]}>
                <Text style={styles.label}>{item.attributes.content}</Text>
                <RadioButton text='' onPress={() => handleRadioPress(item)} size='large' checked={(item.attributes.selected || item.attributes.code === optionSelected) ?? false} />
            </TouchableOpacity>
        );
    };
    const handleRadioPress = (data: registerStaticData) => {
        Props.onSelected?.(data);
        setOptionSelected(data.attributes.code);
    };
    return (
        <View>
            <FlatList
                data={Props.listOption}
                pagingEnabled={true}
                horizontal={false}
                renderItem={renderOption}
                contentContainerStyle={styles.container}
                keyExtractor={(item) => 'key_' + item.id}
                extraData={optionSelected}
            />
        </View>
    )
}


const useStyles = createStyles((theme: Theme) => ({
    container: {
        paddingVertical: theme.Size.Vertical.Medium,
    },
    row: {
        flexDirection: 'row',
        justifyContent: 'space-between',
        alignItems: 'center',
        paddingVertical: theme.Size.vs(10),
    },
    label: {
        ...theme.Typography.TextBody.Regular,
    },
}));
