import React, { useEffect, useState } from 'react';
import { Image, type ImageRequireSource, ScrollView, StyleSheet, Text, View, Alert, Button } from 'react-native';

import { useRoute } from '@react-navigation/native';
import AsyncStorage from '@react-native-async-storage/async-storage';
import FastImage from 'react-native-fast-image';

type ImageInfo = {
    title: string;
    desc: string;
    source: ImageRequireSource;
};

const ImageCard = ({ title, desc, source }: ImageInfo) => {
    return (
        <View style={styles.imageCard}>
            <FastImage source={source} style={styles.image} />
            <View style={styles.titleContainer}>
                <Text style={styles.title}>{title}</Text>
                <Text style={styles.subtitle}>{desc}</Text>
            </View>
        </View>
    );
};

const GalleryScreen: React.FC = () => {
    const route = useRoute();
    const [name, setName] = useState('');

    useEffect(() => {
        const params = route.params as { message: string };
        if (params && params.message) {
            Alert.alert('Message from Food App', params.message);
        }
    }, [route.params]);

    useEffect(() => {
        const fetchData = async () => {
            const storedName = await getData('user_name');
            if (storedName) {
                setName(storedName);
            }
        };
        fetchData();
    }, []);

    const storeData = async (key: string, value: string) => {
        try {
            await AsyncStorage.setItem(key, JSON.stringify(value));
            // console.log('Data stored successfully!');
        } catch (error) {
            console.error('Error storing data:', error);
        }
    };

    const getData = async (key: string) => {
        try {
            const value = await AsyncStorage.getItem(key);
            return value ? setName(JSON.parse(value)) : null;
        } catch (error) {
            console.error('Error reading data:', error);
            return null;
        }
    };

    const images: ImageInfo[] = [
        {
            title: 'KMS AI Assistant',
            desc: 'Empowering the future of work',
            source: require('../../../assets/pic_1.gif'),
        },
        {
            title: 'Digital Engineering',
            desc: 'Transforming and modernizing your business',
            source: require('../../../assets/pic_2.webp'),
        },
        {
            title: 'KMS Gives',
            desc: 'Charity and community activities',
            source: require('../../../assets/pic_3.jpeg'),
        },
    ];

    return (
        <ScrollView contentContainerStyle={styles.contentContainer} style={styles.container}>
            <Text>Local storage Value: {name}</Text>
            <Button title='Save Data in MiniApp' onPress={() => storeData('abcd-mini', 'value-000')} />
            <Button title='Get Data in MiniApp' onPress={() => getData('abcd-mini')} />
            <Button title='Get Data from Host App' onPress={() => getData('abc')} />
            {images.map((item) => (
                <ImageCard key={item.title} title={item.title} desc={item.desc} source={item.source} />
            ))}
        </ScrollView>
    );
};

const styles = StyleSheet.create({
    container: {
        flex: 1,
        backgroundColor: '#F1F3F4FF',
    },
    contentContainer: {
        marginTop: 20,
    },
    imageCard: {
        marginBottom: 20,
        backgroundColor: 'white',
        borderRadius: 10,
        shadowColor: '#27aae1',
        shadowOffset: { width: 0, height: 4 },
        shadowOpacity: 0.15,
        shadowRadius: 32,
        marginHorizontal: 15,
        overflow: 'hidden',
    },
    image: {
        width: '100%',
        height: 250,
        resizeMode: 'cover',
    },
    titleContainer: {
        padding: 15,
    },
    title: {
        fontSize: 18,
        fontWeight: '600',
        color: '#000000',
        marginBottom: 5,
    },
    subtitle: {
        fontSize: 14,
        color: '#27aae1',
        fontWeight: '400',
    },
    message: {
        marginBottom: 12,
        marginHorizontal: 12,
    },
});

export default GalleryScreen;
