import React from 'react';
import { Provider } from 'react-redux';
import MainNavigator from '@src/presentation/navigation/MainNavigator';
import { store } from './lib/redux';
import { GlobalProvider, LanguageProvider } from '@core/service';
import { PortalProvider, ThemeProvider } from '@core/ui';
import { NavigationContainer } from '@react-navigation/native';
import en from './locales/en.json';
import vi from './locales/vi.json';

const STANDALONE = Boolean(process.env.STANDALONE);

function App() {
    return (
        <GlobalProvider>
            <LanguageProvider initOptions={{ resources: { en, vi } }}>
                <Provider store={store}>
                    <ThemeProvider>
                        {STANDALONE ? (
                            <NavigationContainer>
                                <MainNavigator />
                                <PortalProvider />
                            </NavigationContainer>
                        ) : (
                            <>
                                <MainNavigator />
                                <PortalProvider />
                            </>
                        )}
                    </ThemeProvider>
                </Provider>
            </LanguageProvider>
        </GlobalProvider>
    );
}

export default App;
