import {inject} from 'inversify';
import {TYPES} from '@src/di/types/types';
import type { ITnCLendingRepository } from '@src/domain/interfaces/cms/loan_collateral/tnCLending';

export class TnCLendingHandler {
    private readonly _repository: ITnCLendingRepository;

    constructor(
        @inject(TYPES.ITnCLendingRepository)
        tnCLendingRepository: ITnCLendingRepository
    ) {
        this._repository = tnCLendingRepository;
    }

    handle(segment: string) {
        return this._repository.tnCLending(segment);
    }
}
