import { injectable } from 'inversify';
import { Query } from '@src/domain/models/query';
import { HttpService } from '@core/service';
import { BASE_URL_LOAN_API } from '@src/config';
import { store } from '@src/lib/redux';
import { IAddressRepository } from '@src/domain/interfaces/address/address';
import { Province, ProvinceResponse } from '@src/domain/entities/address/province';
import { GetProvincePayload } from '@src/application/address/get_province_payload';
import { DistrictResponse } from '@src/domain/entities/address/district';
import { GetDistrictPayload } from '@src/application/address/get_district_payload';
import { WardResponse } from '@src/domain/entities/address/ward';
import { GetWardPayload } from '@src/application/address/get_ward_payload';
import { commonService } from '@src/infrastructure/network/networkService';

@injectable()
export class AddressRepository
    extends HttpService
    implements IAddressRepository {
    constructor() {
        super({ baseURL: 'https://di-bank-uat.hdbank.com.vn/api/sdk/v1' });
    }

    async getProvinceList<TParameter>(query: Query<TParameter>): Promise<ProvinceResponse> {
        const request = query.query as unknown as GetProvincePayload;
        const url = '/address-provinces';
        const token = store.getState().product.token;
        console.log('\x1b[31m getProvinceList pha_header_getProvinceList', commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-register' }));
        try {
            const response = await this.post(url, request, {
                headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-register' }),
            })
            return response.data as ProvinceResponse;
        } catch (error) {
            throw error;
        }

    }
    async getDistrictList<TParameter>(query: Query<TParameter>): Promise<DistrictResponse> {
        const request = query.query as unknown as GetDistrictPayload;
        const url = '/address-districts';
        const token = store.getState().product.token;
        try {
            const response = await this.post(url, request, {
                headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-register' }),
            })
            return response.data as DistrictResponse;
        } catch (error) {
            throw error;
        }

    }
    async getWardList<TParameter>(query: Query<TParameter>): Promise<WardResponse> {
        const request = query.query as unknown as GetWardPayload;
        const url = '/address-wards';
        const token = store.getState().product.token;
        try {
            const response = await this.post(url, request, {
                headers: commonService.getHeader({ 'X-CHANNEL': 'mfe-loan-register' }),
            })
            return response.data as WardResponse;
        } catch (error) {
            throw error;
        }

    }
}
